"use client";
/* Avocado, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Avocado(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("avocado"); }, []);
  return React.createElement("piix-sprite", { "name": "avocado", ...piixAttrs(props) });
}

export default Avocado;
